class Component extends DCLogic {
  componentDidMount(){ const go=()=>window.SWD?SWD.ready(()=>this.init()):setTimeout(go,30); go(); }
  init(){
    const D=SW_DEMO_DATA, CF=SW_DEMO, $=id=>document.getElementById(id), UF=SWD.UFS(), CT=CF.country, S=SW_GEO.states;
    SWD.page({active:'povos',lv:'BR',label:'Indígenas e quilombolas'});
    const K={
      ind:{n:'Pessoas indígenas',sm:'Indígenas',d:D.ind,src:'ind',terr:'em terras indígenas',
        t:'Pessoas indígenas, por estado',s:'Censo 2022. Cada círculo é proporcional ao número de pessoas.',
        note:'O Censo 2022 contou como indígenas as pessoas que se declararam de cor ou raça indígena e também as que, tendo respondido outra cor ou raça, se consideram indígenas. Por isso o total aqui é maior que a categoria Indígena em Cor ou raça.'},
      qui:{n:'Pessoas quilombolas',sm:'Quilombolas',d:D.qui,src:'qui',terr:'em territórios quilombolas',
        t:'Pessoas quilombolas, por estado',s:'Censo 2022. Cada círculo é proporcional ao número de pessoas.',
        note:'O Censo 2022 foi o primeiro a contar a população quilombola.'}
    };
    const st={k:SWD.q.get('k')||'ind',sel:SWD.q.get('u')||'AM',hov:null};
    SWD.seg($('kind'),Object.entries(K).map(([k,v])=>[k,v.n,v.sm]),st.k,k=>{st.k=k;paint();draw()},'Grupo');
    const map=new SW.Map($('map'),{aria:'Mapa dos estados',onHover:u=>{st.hov=u;draw()},onClick:u=>{st.sel=u;draw()}});
    map.update({fill:()=>({f:'var(--g0)',k:0})});
    const svg=map.svg, bub=document.createElementNS('http://www.w3.org/2000/svg','g'); svg.insertBefore(bub,svg.querySelector('.g-cl'));
    const rank=new SW2.Ranking($('rank'),{onHover:u=>{st.hov=u;draw()},onClick:u=>{st.sel=u;draw()}});
    const paint=()=>{ const k=K[st.k], mx=Math.max(...UF.map(u=>k.d[u][0]||0)), R=v=>Math.sqrt(v/mx)*52;
      $('vt').textContent=k.t; $('vs').textContent=k.s; $('vstamp').innerHTML=SWD.stamp(k.src); $('note').innerHTML=SW2.note(k.note); $('src').innerHTML=SWD.srcLine([k.src]);
      bub.innerHTML=UF.filter(u=>k.d[u][0]).sort((a,b)=>k.d[b][0]-k.d[a][0]).map(u=>`<circle class="bub" data-c="${u}" cx="${S[u].c[0]}" cy="${S[u].c[1]}" r="${R(k.d[u][0]).toFixed(1)}"/>`).join('');
      const ex=[mx,mx/4,mx/16].map(v=>Math.round(v/1000)*1000);
      $('lg').innerHTML=`<svg width="120" height="${R(mx)*2+4}" aria-hidden="true">${ex.map(v=>`<circle cx="${R(mx)+2}" cy="${R(mx)*2+2-R(v)}" r="${R(v)}" style="fill:none;stroke:var(--sub)"/>`).join('')}</svg><div style="display:grid;gap:4px">${ex.map(v=>`<span>${SWD.mi(v)} pessoas</span>`).join('')}</div>`;
    };
    const draw=()=>{ const k=K[st.k], u=st.hov||st.sel, v=k.d[u], rr=SW2.rankOf(Object.fromEntries(UF.map(x=>[x,k.d[x][0]])),u);
      map.mark(st.sel,st.hov); bub.querySelectorAll('circle').forEach(c=>c.classList.toggle('on',c.dataset.c===u));
      const inT=v[2], sh=v[0]&&inT!=null?inT/v[0]*100:null;
      $('card').innerHTML=`<div class="card" aria-live="polite">
        <div class="meta">${SWD.region(u)} · ${rr.rank?`${rr.rank}º de ${rr.of} em número de pessoas`:'sem dado'}</div>
        <div class="row1"><div class="nm">${SWD.name(u)}</div>${v[0]==null?SWD.nodata():`<div class="big">${SWD.mi(v[0])}<small>pessoas</small></div>`}</div>
        ${v[0]==null?'':`<div class="facts"><div class="fact"><span>Parte da população do estado</span><b>${SWD.pct(v[1],2)}</b></div>
          <div class="fact"><span>Moram ${k.terr}</span><b>${inT==null?'sem dado':`${SWD.int(inT)} · ${SWD.pct(sh,0)}`}</b></div>
          <div class="fact"><span>${CT.name}, total</span><b>${SWD.int(k.d.BR[0])}</b></div></div>`}
        <div style="margin-top:4px">${SWD.stamp(k.src)}</div></div>`;
      rank.render({rows:UF.map(x=>({uf:x,v:k.d[x][0],txt:SWD.mi(k.d[x][0],true)})),sel:st.sel,hov:st.hov,col:'Pessoas',head:'Estado',plural:'estados'});
    };
    paint(); draw();
  }
  renderVals(){ return {}; }
}
